import json
import requests
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from threading import Lock

def process_task(task):
    url = task["url"]
    expr = task["expr"]
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        data = response.json()
    except (requests.RequestException, json.JSONDecodeError):
        return {"url": url, "result": "error"}
    try:
        result = eval(expr, {"__builtins__": None}, data)
    except Exception:
        return {"url": url, "result": "error"}
    return {"url": url, "result": result}

def main():
    with open("tasks.json", "r") as f:
        tasks = json.load(f)

    rate_limit = 4
    delay = 1.0 / rate_limit
    lock = Lock()
    results = []

    with ThreadPoolExecutor() as executor:
        futures = []
        for task in tasks:
            future = executor.submit(process_task, task)
            futures.append(future)

        for future in as_completed(futures):
            result = future.result()
            with lock:
                results.append(result)
                time.sleep(delay)

    for result in results:
        print(json.dumps(result))

if __name__ == "__main__":
    main()

import json
import requests
import time
from threading import Thread
from queue import Queue

def process_task(task):
    try:
        response = requests.get(task['url'], timeout=5)
        if not response.ok:
            return {"url": task['url'], "result": "error"}
        data = response.json()
        try:
            result = eval(task['expr'], {'__builtins__': None}, {'data': data})
            return {"url": task['url'], "result": result}
        except:
            return {"url": task['url'], "result": "error"}
    except:
        return {"url": task['url'], "result": "error"}

def worker(task_queue):
    while True:
        task = task_queue.get()
        if task is None:  # Sentinel value to stop the worker
            task_queue.task_done()
            break
        result = process_task(task)
        task_queue.task_done()
        print(json.dumps(result))

def main():
    with open('tasks.json', 'r') as f:
        tasks = json.load(f)

    task_queue = Queue()
    for task in tasks:
        task_queue.put(task)

    # Start 4 worker threads
    threads = []
    for _ in range(4):
        t = Thread(target=worker, args=(task_queue,))
        t.start()
        threads.append(t)

    # Wait for all tasks to be processed
    task_queue.join()

    # Stop workers
    for _ in range(4):
        task_queue.put(None)
    for t in threads:
        t.join()

if __name__ == "__main__":
    main()

